using Microsoft.EntityFrameworkCore;

// Cosmos DB project fixes for EF Core 9 breaking changes
class CosmosDbContext : DbContext
{
    public DbSet<Product> Products => Set<Product>();

    protected override void OnConfiguring(DbContextOptionsBuilder options)
    {
        options.UseCosmos(
            "AccountEndpoint=https://localhost:8081/;AccountKey=...",
            "CatalogDb");
    }

    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        // BREAKING CHANGE 1: EF Core 9 renamed the default discriminator property
        // from "Discriminator" to "$type". Existing documents use "Discriminator",
        // so you must explicitly configure it to preserve backward compatibility.
        modelBuilder.Entity<Product>().HasDiscriminator<string>("Discriminator");
    }

    // BREAKING CHANGE 2: Synchronous Cosmos DB queries now throw
    // InvalidOperationException in EF Core 9. All queries must be async.
    //
    // BEFORE (EF8 - no longer works):
    //   var items = db.Products.ToList();
    //   var item  = db.Products.First(p => p.Id == id);
    //
    // AFTER (EF9 - required):
    //   var items = await db.Products.ToListAsync();
    //   var item  = await db.Products.FirstAsync(p => p.Id == id);
}

class Product
{
    public string Id { get; set; } = default!;
    public string Name { get; set; } = default!;
}

